"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[22975],{69931:e=>{e.exports=JSON.parse('{"functions":[{"name":"SetTrigger","desc":"The single trigger path: mouse input and the HUD\'s touch fire button\\n(`Signals.TurretTrigger`).","params":[{"name":"down","desc":"","lua_type":"boolean"}],"returns":[],"function_type":"static","source":{"line":116,"path":"src/StarterPlayer/StarterPlayerScripts/TrainTurret/Gunner.luau"}},{"name":"Mounted","desc":"The Model the local player mans right now, or nil.","params":[],"returns":[{"desc":"","lua_type":"Model?\\n"}],"function_type":"static","source":{"line":133,"path":"src/StarterPlayer/StarterPlayerScripts/TrainTurret/Gunner.luau"}},{"name":"attach","desc":"Adds the mount prompt to a placed turret (`promptPart` is its mount prompt\\npart). Everything it makes goes into `cleaner`.","params":[{"name":"model","desc":"","lua_type":"Model"},{"name":"promptPart","desc":"","lua_type":"BasePart"},{"name":"cleaner","desc":"","lua_type":"Janitor.Janitor"},{"name":"def","desc":"","lua_type":"GunnerDef"}],"returns":[],"function_type":"static","source":{"line":275,"path":"src/StarterPlayer/StarterPlayerScripts/TrainTurret/Gunner.luau"}}],"properties":[],"types":[],"name":"Gunner","desc":"The local player\'s controls for any train turret. One module instance serves\\nevery turret controller (BurstCannon, Sturmlanze, ...): one mount at a\\ntime. A controller calls `attach` per placed turret with a `GunnerDef` that\\nnames its config, its three packets and its weapon hooks; nothing here knows\\na weapon.\\n\\n`attach` puts a mount `ProximityPrompt` on a placed turret\'s prompt part, plus\\nthe Stash (hold F) and Move (hold G) prompts from `PlaceableActions.addPrompts`.\\nAll three hide while anyone mans the turret or the local player mans any\\nturret. Triggering mount sends `def.MountPacket(model)`; the server seats the\\nplayer and its answer plus the gunner attribute are the source of truth.\\n\\nWhile mounted: the CameraController aim mode keeps the mouse locked to the\\ncentre and shows the reticle; each frame the camera-centre ray gives the aim\\npoint, the local yaw/pitch turn toward it at `YawSpeed`/`PitchSpeed` and drive\\nthe local `TurretRig` (`External = true`), `def.AimPacket` goes out at\\n`AimReportHz`, then `def.OnStep` runs (the weapon\'s shot prediction).\\nMouseButton1 and the HUD\'s touch FIRE button -> `SetTrigger`, X -> leave,\\nany other key -> `def.OnKey`.\\n\\nLeaving (X, death, turret removed, or the gunner attribute no longer the local\\nplayer, which covers a jump-off and a failed sit) restores the camera and the\\nmouse and fires `Signals.OnTurretMounted(nil)`.\\n\\nThe per-frame step binds itself once, at `Camera + 3` (after the camera and its shake, so\\nthe centre ray is current). Controllers update their rigs at `Camera + 4`, so\\nthe local aim always lands before the rigs update.","realm":["Client"],"source":{"line":34,"path":"src/StarterPlayer/StarterPlayerScripts/TrainTurret/Gunner.luau"}}')}}]);